-- Aggregates contain no user-level payloads. Only checked admin RPCs may read them.
create table kiyi_private.ops_stat_cache(key text primary key,payload jsonb not null,generated_at timestamptz not null);
create table kiyi_private.ops_gift_daily(day date not null,product text not null,sent bigint not null default 0,credits bigint not null default 0,primary key(day,product));
create table kiyi_private.ops_usage_readings(metric text primary key,used numeric check(used>=0),observed_at timestamptz,period_start timestamptz,period_end timestamptz,source text not null default 'not_connected');
create table kiyi_private.ops_usage_alerts(metric text primary key,first_seen timestamptz not null default now(),last_seen timestamptz not null default now(),resolved_at timestamptz,used numeric not null,quota numeric not null);
do $$declare t text;begin foreach t in array array['ops_stat_cache','ops_gift_daily','ops_usage_readings','ops_usage_alerts'] loop execute format('alter table kiyi_private.%I enable row level security',t);execute format('revoke all on kiyi_private.%I from public,anon,authenticated',t);end loop;end $$;
create index ops_activity_day_user on kiyi_private.ops_activity(day,user_id);
insert into kiyi_private.ops_gift_daily select (to_timestamp(created/1000.0) at time zone 'Europe/Istanbul')::date,product,count(*),sum(credits) from public.kiyi_gifts group by 1,2;
create function kiyi_private.ops_gift_rollup() returns trigger language plpgsql security definer set search_path='' as $$begin
 if TG_OP in ('DELETE','UPDATE') then update kiyi_private.ops_gift_daily set sent=sent-1,credits=credits-OLD.credits where day=(to_timestamp(OLD.created/1000.0)at time zone 'Europe/Istanbul')::date and product=OLD.product;end if;
 if TG_OP in ('INSERT','UPDATE') then insert into kiyi_private.ops_gift_daily(day,product,sent,credits)values((to_timestamp(NEW.created/1000.0)at time zone 'Europe/Istanbul')::date,NEW.product,1,NEW.credits) on conflict(day,product)do update set sent=kiyi_private.ops_gift_daily.sent+1,credits=kiyi_private.ops_gift_daily.credits+excluded.credits;end if;return null;
end $$;
revoke all on function kiyi_private.ops_gift_rollup() from public,anon,authenticated;
create trigger kiyi_gift_statistics after insert or update or delete on public.kiyi_gifts for each row execute function kiyi_private.ops_gift_rollup();

-- A trusted collector can import official organisation usage. No client or admin JWT may call this.
create function kiyi_private.ops_import_provider_usage(metric_key text,used_value numeric,period_from timestamptz,period_to timestamptz,observed timestamptz)returns void language plpgsql security definer set search_path='' as $$begin
 if metric_key is null or used_value::text in ('NaN','Infinity','-Infinity') or metric_key not in ('egress','cached_egress','auth_mau','realtime_messages','realtime_connections') or used_value is null or used_value<0 or period_from is null or period_to is null or period_to<=period_from or observed is null or observed>now()+interval '5 minutes' or observed<now()-interval '1 day' or now() not between period_from and period_to then raise exception 'INVALID_USAGE_SAMPLE';end if;
 insert into kiyi_private.ops_usage_readings values(metric_key,used_value,observed,period_from,period_to,'provider_import')on conflict(metric)do update set used=excluded.used,observed_at=excluded.observed_at,period_start=excluded.period_start,period_end=excluded.period_end,source=excluded.source where kiyi_private.ops_usage_readings.observed_at is null or kiyi_private.ops_usage_readings.observed_at<=excluded.observed_at;
end $$;
revoke all on function kiyi_private.ops_import_provider_usage(text,numeric,timestamptz,timestamptz,timestamptz) from public,anon,authenticated,service_role;

create function kiyi_private.ops_refresh_statistics()returns jsonb language plpgsql security definer set search_path='' as $$
declare today date=(now()at time zone 'Europe/Istanbul')::date; overview jsonb;analytics jsonb;usage jsonb;row_data record;bytes numeric;missing bigint;
begin
 if not pg_try_advisory_xact_lock(hashtextextended('kiyi-statistics-refresh',0)) then return jsonb_build_object('skipped',true);end if;
 overview=jsonb_build_object('users',(select count(*) from public.kiyi_profiles where deleted_at is null),'dau',(select count(*) from kiyi_private.ops_activity where day=today),'wau',(select count(distinct user_id) from kiyi_private.ops_activity where day>=today-6),'mau',(select count(distinct user_id) from kiyi_private.ops_activity where day>=today-29),'online',(select count(*) from kiyi_private.ops_presence where last_seen>now()-interval '90 seconds'),'map_active',(select count(*) from public.kiyi_positions l join public.kiyi_privacy q using(user_id)join public.kiyi_regions rg on rg.id=l.region where q.sharing and l.received_at>now()-interval '90 seconds' and rg.active and kiyi_private.account_active(l.user_id)),'ghost_active',(select count(*) from public.kiyi_positions l join public.kiyi_privacy q using(user_id)join public.kiyi_regions rg on rg.id=l.region where q.sharing and q.ghost and rg.active and l.received_at>now()-interval '90 seconds' and kiyi_private.account_active(l.user_id)),'premium',(select count(*) from public.kiyi_entitlements where premium_until>now() and kiyi_private.account_active(user_id)),'pending_reports',(select count(*) from public.kiyi_reports where status='pending'),'gifts',(select coalesce(sum(sent),0) from kiyi_private.ops_gift_daily where product<>'song'),'songs',(select coalesce(sum(sent),0) from kiyi_private.ops_gift_daily where product='song'),'payments_connected',false,'activity_since',(select min(day) from kiyi_private.ops_activity),'as_of',now(),'refresh_seconds',300);
 analytics=jsonb_build_object('daily',(select coalesce(jsonb_agg(to_jsonb(z)),'[]') from(select day,count(*) active_users from kiyi_private.ops_activity where day>=today-29 group by day order by day)z),'gift_top',(select coalesce(jsonb_agg(to_jsonb(z)),'[]') from(select product,sum(sent) sent,sum(credits) credits from kiyi_private.ops_gift_daily group by product having sum(sent)>0 order by sum(sent)desc,product)z),'regions',(select coalesce(jsonb_agg(to_jsonb(z)),'[]') from(select * from kiyi_private.ops_metrics where day>=today-29 order by day desc,region)z),'revenue',null,'as_of',now(),'refresh_seconds',300,'note','İstatistikler 5 dakikada bir hazırlanır. Gelir sağlayıcısı bağlı değil. Aktiflik yalnız ölçümün başladığı tarihten itibaren tutulur.');
 insert into kiyi_private.ops_stat_cache values('overview',overview,now()),('analytics',analytics,now())on conflict(key)do update set payload=excluded.payload,generated_at=excluded.generated_at;
 -- Project observations are lower bounds for organisation-wide storage; not a billing API.
 insert into kiyi_private.ops_usage_readings values('database',pg_database_size(current_database()),now(),null,null,'project_database')on conflict(metric)do update set used=excluded.used,observed_at=excluded.observed_at,source=excluded.source;
 select coalesce(sum(case when metadata->>'size'~'^[0-9]+$' then (metadata->>'size')::numeric else 0 end),0),count(*)filter(where coalesce(metadata->>'size','')!~'^[0-9]+$')into bytes,missing from storage.objects;
 insert into kiyi_private.ops_usage_readings values('storage',case when missing=0 then bytes else null end,now(),null,null,case when missing=0 then 'project_storage_lower_bound' else 'incomplete_metadata' end)on conflict(metric)do update set used=excluded.used,observed_at=excluded.observed_at,source=excluded.source;
 usage=jsonb_build_object('as_of',now(),'threshold_percent',75,'automatic_delivery','admin_panel','note','Veritabanı bu projenin tamamını kapsar. Depolama bu projenin ölçümüdür; organizasyon toplamı daha yüksek olabilir. Veri çıkışı, Auth MAU ve Realtime için resmî kullanım kaynağı bağlanmalıdır. MB/GB hesabı ondalık bayt üzerinden erken uyarı verir; Supabase kullanım ekranı esastır.','items',(select jsonb_agg(jsonb_build_object('metric',q.metric,'label',q.label,'quota',q.quota,'unit',q.unit,'used',case when s.observed_at>now()-interval '1 hour' and (s.period_end is null or now()between s.period_start and s.period_end) then s.used else null end,'observed_at',s.observed_at,'source',coalesce(s.source,'not_connected'),'warning_at',q.quota*.75,'status',case when s.used is null or s.observed_at is null or s.observed_at<=now()-interval '1 hour' or (s.period_end is not null and not(now()between s.period_start and s.period_end))then 'unknown' when s.used>=q.quota*.75 then 'warning' else 'normal' end)order by q.n)from(values(1,'database','Veritabanı',500000000::numeric,'bytes'),(2,'storage','Dosya depolama',1000000000::numeric,'bytes'),(3,'egress','Aylık veri çıkışı',5000000000::numeric,'bytes'),(4,'cached_egress','Aylık önbellek veri çıkışı',5000000000::numeric,'bytes'),(5,'auth_mau','Aylık aktif Auth kullanıcı',50000::numeric,'count'),(6,'realtime_messages','Aylık Realtime mesajı',2000000::numeric,'count'),(7,'realtime_connections','Tepe Realtime bağlantısı',200::numeric,'count'))q(n,metric,label,quota,unit)left join kiyi_private.ops_usage_readings s on s.metric=q.metric));
 for row_data in select * from jsonb_to_recordset(usage->'items')as x(metric text,status text,used numeric,quota numeric)loop
  if row_data.status='warning' then insert into kiyi_private.ops_usage_alerts(metric,used,quota)values(row_data.metric,row_data.used,row_data.quota)on conflict(metric)do update set used=excluded.used,quota=excluded.quota,last_seen=now(),first_seen=case when kiyi_private.ops_usage_alerts.resolved_at is not null then now() else kiyi_private.ops_usage_alerts.first_seen end,resolved_at=null;
  elsif row_data.status='normal' then update kiyi_private.ops_usage_alerts set resolved_at=now()where metric=row_data.metric and resolved_at is null;end if;
 end loop;
 usage=usage||jsonb_build_object('alerts',(select coalesce(jsonb_agg(to_jsonb(a)),'[]')from kiyi_private.ops_usage_alerts a where resolved_at is null));
 insert into kiyi_private.ops_stat_cache values('usage',usage,now())on conflict(key)do update set payload=excluded.payload,generated_at=excluded.generated_at;
 insert into kiyi_private.ops_job_runs values('statistics_refresh',now(),jsonb_build_object('ok',true,'cache_keys',3))on conflict(job)do update set last_run=excluded.last_run,last_result=excluded.last_result;
 return jsonb_build_object('ok',true,'as_of',now());
end $$;
revoke all on function kiyi_private.ops_refresh_statistics() from public,anon,authenticated,service_role;
